from collections import defaultdict

class Twitter:
    def __init__(self):
        self.time = 0
        self.following = defaultdict(set)
        self.posts = defaultdict(list)   # userId -> [(time, tweetId)]

    def post_tweet(self, user_id, tweet_id):
        self.following[user_id].add(user_id)
        self.posts[user_id].append((self.time, tweet_id))
        self.time += 1

    def get_news_feed(self, user_id):
        candidates = []
        for followee in self.following[user_id] | {user_id}:
            candidates.extend(self.posts[followee])
        candidates.sort(reverse=True)
        return [tweet_id for _, tweet_id in candidates[:10]]

    def follow(self, follower_id, followee_id):
        self.following[follower_id].add(followee_id)

    def unfollow(self, follower_id, followee_id):
        self.following[follower_id].discard(followee_id)

