#include <bits/stdc++.h>
using namespace std;

class Twitter {
    int time = 0;
    unordered_map<int, unordered_set<int>> following;
    unordered_map<int, deque<pair<int, int>>> posts;  // {time, tweetId}
public:
    void postTweet(int userId, int tweetId) {
        following[userId].insert(userId);
        posts[userId].push_back({time++, tweetId});
    }
    vector<int> getNewsFeed(int userId) {
        set<pair<int, int>, greater<pair<int, int>>> all;
        for (int f : following[userId])
            for (auto& post : posts[f]) all.insert(post);
        vector<int> feed;
        for (auto it = all.begin(); it != all.end() && (int)feed.size() < 10; ++it)
            feed.push_back(it->second);
        return feed;
    }
    void follow(int followerId, int followeeId) { following[followerId].insert(followeeId); }
    void unfollow(int followerId, int followeeId) { following[followerId].erase(followeeId); }
};

