import java.util.*;

class Twitter {
    private int time = 0;
    private Map<Integer, Set<Integer>> following = new HashMap<>();
    private Map<Integer, List<long[]>> posts = new HashMap<>();  // {time, tweetId}

    public void postTweet(int userId, int tweetId) {
        following.computeIfAbsent(userId, k -> new HashSet<>()).add(userId);
        posts.computeIfAbsent(userId, k -> new ArrayList<>()).add(new long[]{time++, tweetId});
    }

    public List<Integer> getNewsFeed(int userId) {
        List<long[]> all = new ArrayList<>();
        for (int f : following.getOrDefault(userId, Set.of(userId)))
            all.addAll(posts.getOrDefault(f, List.of()));
        all.sort((a, b) -> Long.compare(b[0], a[0]));
        List<Integer> feed = new ArrayList<>();
        for (int i = 0; i < Math.min(10, all.size()); ++i) feed.add((int) all.get(i)[1]);
        return feed;
    }

    public void follow(int followerId, int followeeId) {
        following.computeIfAbsent(followerId, k -> new HashSet<>()).add(followeeId);
    }

    public void unfollow(int followerId, int followeeId) {
        Set<Integer> set = following.get(followerId);
        if (set != null) set.remove(followeeId);
    }
}
